const { randomUUID } = require("crypto");

const commands = new Map();

function enqueueLaunch(app) {
  const command = {
    id: randomUUID(),
    type: "launch",
    app: {
      id: app.id,
      name: app.name,
    },
    status: "pending",
    createdAt: Date.now(),
  };

  commands.set(command.id, command);
  return command;
}

function getNextCommand() {
  const now = Date.now();

  for (const [id, command] of commands) {
    if (now - command.createdAt > 5 * 60 * 1000) {
      commands.delete(id);
      continue;
    }

    if (command.status === "pending") {
      command.status = "processing";
      return command;
    }
  }

  return null;
}

function completeCommand(id, result) {
  const command = commands.get(id);

  if (!command || command.status !== "processing") {
    return false;
  }

  command.status = result.success ? "completed" : "failed";
  command.result = {
    success: Boolean(result.success),
    message: String(result.message || "").slice(0, 300),
  };
  command.completedAt = Date.now();

  return true;
}

module.exports = {
  enqueueLaunch,
  getNextCommand,
  completeCommand,
};

require("dotenv").config();

const fs = require("fs");
const path = require("path");
const { spawn } = require("child_process");

const SERVER_URL = (
  process.env.DESKPILOT_SERVER_URL || ""
).replace(/\/+$/, "");

const AGENT_TOKEN = process.env.DESKPILOT_AGENT_TOKEN;

const APPS_FILE = path.join(__dirname, "apps.local.json");
const POLL_INTERVAL = 3000;

if (!SERVER_URL || !AGENT_TOKEN) {
  console.error(
    "Missing DESKPILOT_SERVER_URL or DESKPILOT_AGENT_TOKEN in .env"
  );
  process.exit(1);
}

if (process.platform !== "win32") {
  console.error("DeskPilot Agent must run on Windows.");
  process.exit(1);
}

function loadApps() {
  const data = JSON.parse(fs.readFileSync(APPS_FILE, "utf8"));

  if (!Array.isArray(data)) {
    throw new Error("apps.local.json must contain an array");
  }

  return data;
}

async function apiRequest(endpoint, options = {}) {
  const response = await fetch(`${SERVER_URL}${endpoint}`, {
    ...options,
    headers: {
      Authorization: `Bearer ${AGENT_TOKEN}`,
      "Content-Type": "application/json",
      ...options.headers,
    },
    signal: AbortSignal.timeout(15000),
  });

  const data = await response.json().catch(() => ({}));

  if (!response.ok) {
    throw new Error(
      `API ${response.status}: ${data.message || "Request failed"}`
    );
  }

  return data;
}

function launchApplication(app) {
  return new Promise((resolve, reject) => {
    if (
      typeof app.path !== "string" ||
      !path.win32.isAbsolute(app.path) ||
      path.win32.extname(app.path).toLowerCase() !== ".exe"
    ) {
      return reject(new Error("Invalid executable path"));
    }

    if (!fs.existsSync(app.path)) {
      return reject(new Error("Executable not found on this laptop"));
    }

    const child = spawn(app.path, [], {
      shell: false,
      detached: true,
      stdio: "ignore",
      windowsHide: false,
    });

    child.once("error", reject);

    child.once("spawn", () => {
      child.unref();
      resolve();
    });
  });
}

async function reportResult(commandId, success, message) {
  return apiRequest(
    `/api/agent/commands/${encodeURIComponent(commandId)}/result`,
    {
      method: "POST",
      body: JSON.stringify({ success, message }),
    }
  );
}

async function processCommand(command) {
  if (
    !command ||
    typeof command.id !== "string" ||
    command.type !== "launch" ||
    !command.app ||
    typeof command.app.id !== "string"
  ) {
    console.error("Received an invalid command.");
    return;
  }

  let result = {
    success: false,
    message: "Launch failed",
  };

  try {
    const apps = loadApps();

    // Only launch apps explicitly configured in the local allowlist.
    const app = apps.find(
      (item) => item.id === command.app.id
    );

    if (!app) {
      throw new Error(
        `App ID ${command.app.id} is not in apps.local.json`
      );
    }

    await launchApplication(app);

    result = {
      success: true,
      message: `${app.name} launched successfully`,
    };

    console.log(result.message);
  } catch (error) {
    result.message = error.message;
    console.error("Launch failed:", error.message);
  }

  try {
    await reportResult(command.id, result.success, result.message);
    console.log("Command result reported to Render.");
  } catch (error) {
    console.error("Could not report command result:", error.message);
  }
}

async function poll() {
  try {
    const data = await apiRequest("/api/agent/commands/next");

    if (data.command) {
      console.log("Received launch command:", data.command.id);
      await processCommand(data.command);
    }
  } catch (error) {
    console.error("Polling error:", error.message);
  }
}

async function start() {
  loadApps();

  console.log("DeskPilot Windows Agent started.");
  console.log("Backend:", SERVER_URL);
  console.log("Configured apps:", loadApps().length);

  while (true) {
    await poll();
    await new Promise((resolve) =>
      setTimeout(resolve, POLL_INTERVAL)
    );
  }
}

start().catch((error) => {
  console.error("Agent startup failed:", error.message);
  process.exit(1);
});

function launchApp(req, res) {
  try {
    const apps = readApps();
    const app = apps.find((item) => item.id === req.params.id);

    if (!app) {
      return res.status(404).json({
        success: false,
        message: "Application not found",
      });
    }

    // Render/Linux: queue command for the Windows Agent.
    if (process.platform !== "win32") {
      const command = enqueueLaunch(app);

      return res.status(202).json({
        success: true,
        message: `${app.name} launch command queued`,
        commandId: command.id,
        status: command.status,
        app: {
          id: app.id,
          name: app.name,
        },
      });
    }

    // Local Windows backend: launch directly.
    if (
      typeof app.executablePath !== "string" ||
      !path.win32.isAbsolute(app.executablePath) ||
      path.win32.extname(app.executablePath).toLowerCase() !== ".exe" ||
      !fs.existsSync(app.executablePath)
    ) {
      return res.status(400).json({
        success: false,
        message: "Configured executable is invalid or missing",
      });
    }

    const child = spawn(app.executablePath, [], {
      shell: false,
      detached: true,
      stdio: "ignore",
      windowsHide: false,
    });

    child.once("error", (error) => {
      console.error("Launch error:", error.message);
    });

    child.once("spawn", () => {
      child.unref();
    });

    return res.status(202).json({
      success: true,
      message: `${app.name} launch requested`,
      app: {
        id: app.id,
        name: app.name,
      },
    });
  } catch (error) {
    console.error("Launch error:", error.message);

    return res.status(500).json({
      success: false,
      message: "Application launch failed",
    });
  }
}

const {
  getNextCommand,
  completeCommand,
} = require("../utils/agentQueue");

// GET /api/agent/commands/next
function getCommand(req, res) {
  try {
    const command = getNextCommand();

    return res.status(200).json({
      success: true,
      command,
    });
  } catch (error) {
    console.error("Get agent command error:", error.message);

    return res.status(500).json({
      success: false,
      message: "Could not fetch command",
    });
  }
}

// POST /api/agent/commands/:id/result
function reportResult(req, res) {
  try {
    const { success, message } = req.body;

    if (
      typeof success !== "boolean" ||
      typeof message !== "string"
    ) {
      return res.status(400).json({
        success: false,
        message: "A boolean success and string message are required",
      });
    }

    const updated = completeCommand(req.params.id, {
      success,
      message,
    });

    if (!updated) {
      return res.status(404).json({
        success: false,
        message: "Command not found or already completed",
      });
    }

    return res.status(200).json({
      success: true,
      message: "Command result received",
    });
  } catch (error) {
    console.error("Report agent result error:", error.message);

    return res.status(500).json({
      success: false,
      message: "Could not save command result",
    });
  }
}

module.exports = {
  getCommand,
  reportResult,
};

function authenticateAgent(req, res, next) {
  const expectedToken = process.env.DESKPILOT_AGENT_TOKEN;
  const authHeader = req.headers.authorization;

  if (!expectedToken) {
    return res.status(500).json({
      success: false,
      message: "Agent authentication is not configured",
    });
  }

  if (authHeader !== `Bearer ${expectedToken}`) {
    return res.status(401).json({
      success: false,
      message: "Unauthorized agent",
    });
  }

  next();
}

module.exports = authenticateAgent;

